const D = { scale:1, density:.7, lid:.8, hue:210, energy:.6, speed:1, x:.5, y:.66, shimmer:.5, candela:0, seed:0, style:'concert', act:'recital' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const st = P.style;
const hue = ((P.hue%360)+360)%360;
const cx = P.x*width, cy = P.y*height;
const s = u*P.scale;
const lidOpen = Math.max(0, Math.min(1, P.lid));
const nWhite = Math.max(10, Math.min(30, Math.round(12 + P.density*16)));
const nCandle = Math.max(0, Math.min(3, Math.round(P.candela)));

S.mid = (S.mid||0)*.8 + (A.mid||0)*.2;
S.bass = (S.bass||0)*.82 + (A.bass||0)*.18;

if (S.lt == null || K.t < S.lt) S.lt = K.t;
let dt = K.t - S.lt; S.lt = K.t;
if (dt < 0 || dt > 0.2) dt = 1/60;

function pal(){
  if (st==='xray')     return { body:[hue,60,10], sheen:[hue,50,90], key:[hue,30,70], sharp:[hue,55,40], gold:[hue,60,95], spot:[hue,50,60], wire:true };
  if (st==='moonlit')  return { body:[220,45,9], sheen:[210,25,90], key:[210,8,90], sharp:[220,40,14], gold:[200,20,80], spot:[210,30,80] };
  if (st==='gilded')   return { body:[28,30,10], sheen:[40,40,88], key:[40,12,92], sharp:[30,50,14], gold:[45,80,95], spot:[38,45,85], warm:true };
  if (st==='thermal')  return { body:[250,60,8], sheen:[30,90,95], key:[55,70,90], sharp:[280,55,18], gold:[15,90,90], spot:[40,90,85], therm:true };
  // concert (default): glossy black lacquer, warm spot
  return { body:[hue,35,7], sheen:[hue,20,92], key:[hue,5,94], sharp:[hue,30,10], gold:[45,60,88], spot:[hue,30,78] };
}
const C = pal();

// piano silhouette control points (unit, relative to center)
const WING = [[-.36,.11],[.30,.11],[.34,.03],[.30,-.10],[.16,-.21],[-.04,-.24],[-.26,-.18],[-.37,-.04]];
function wingShape(g, ox, oy, k){ g.beginShape();
  const pts = WING; for (let i=-1;i<=pts.length;i++){ const p=pts[(i+pts.length)%pts.length]; g.curveVertex(cx+ox+p[0]*s*k, cy+oy+p[1]*s*k); } g.endShape(CLOSE); }

// keyboard geometry (front straight edge)
const kbL = cx - 0.34*s, kbR = cx + 0.28*s, kbY = cy + 0.115*s, kbH = 0.055*s;
const kw = (kbR-kbL)/nWhite;

// ---- cached body / lid / keybed ----
const bkey = width+'x'+height+':'+st+':'+P.seed+':'+P.scale.toFixed(2)+':'+lidOpen.toFixed(2)+':'+P.x.toFixed(2)+':'+P.y.toFixed(2)+':'+nWhite;
if (!S.bg || S.bgKey !== bkey){
  S.bgKey = bkey;
  const g = (S.bg && S.bg.width===width && S.bg.height===height) ? S.bg : (S.bg = createGraphics(width,height));
  g.colorMode(HSB,360,100,100,100); g.clear(); g.push();

  if (C.wire){
    // xray/blueprint: wireframe grand + string harp + key grid
    g.noFill(); g.stroke(C.sheen[0],C.sheen[1],C.sheen[2],80); g.strokeWeight(Math.max(1,u*0.0014));
    wingShape(g, 0, 0, 1);
    wingShape(g, -0.02*s/s*0+ -lidOpen*0.05*s, -lidOpen*0.12*s, 1.0); // raised lid outline
    // strings radiating (the harp)
    g.stroke(C.spot[0],C.spot[1],C.spot[2],45);
    for (let i=0;i<22;i++){ const t=i/21; g.line(cx-0.30*s+t*0.5*s, cy+0.08*s, cx-0.02*s+t*0.36*s, cy-0.20*s); }
    // key grid
    g.stroke(C.key[0],C.key[1],C.key[2],70);
    for (let i=0;i<=nWhite;i++){ const x=kbL+i*kw; g.line(x, kbY, x, kbY+kbH); }
    g.line(kbL,kbY,kbR,kbY); g.line(kbL,kbY+kbH,kbR,kbY+kbH);
    g.pop();
  } else {
    g.noStroke();
    // floor contact shadow
    g.fill(0,0,0,55); g.ellipse(cx, cy+0.15*s, s*0.8, s*0.12);
    // legs
    g.fill(C.body[0],C.body[1],C.body[2]*0.7,100);
    g.rect(kbL+kw*1.5, kbY, s*0.02, s*0.16, s*0.006);
    g.rect(kbR-kw*1.5, kbY, s*0.02, s*0.16, s*0.006);
    g.rect(cx+0.24*s, cy-0.02*s, s*0.02, s*0.16, s*0.006);
    // ---- raised lid (underside, lighter) shifted up-left ----
    const lox = -lidOpen*0.05*s, loy = -lidOpen*0.20*s;
    g.fill(C.body[0],C.body[1]*1.2,C.body[2]*1.9+3,100); wingShape(g, lox, loy, 1.0);
    // lid prop stick
    g.stroke(C.gold[0],C.gold[1],C.gold[2]*0.7,100); g.strokeWeight(s*0.006);
    g.line(cx+0.10*s, cy-0.02*s, cx+0.10*s+lox*0.6, cy-0.02*s+loy*0.9); g.noStroke();
    // ---- main body (glossy black) ----
    g.fill(C.body[0],C.body[1],C.body[2],100); wingShape(g, 0, 0, 1);
    // deep inner rim shadow
    g.fill(C.sharp[0],C.sharp[1],C.sharp[2]*0.5,100); wingShape(g, 0.008*s, 0.006*s, 0.9);
    // gold trim rim (thin bright edge, hard specular language)
    g.noFill(); g.stroke(C.gold[0],C.gold[1],C.gold[2], C.warm?90:60); g.strokeWeight(Math.max(1,u*0.0016));
    wingShape(g, 0, 0, 0.995); g.noStroke();
    // cast-iron plate hint inside (few gold arcs)
    g.stroke(C.gold[0],C.gold[1]*0.7,C.gold[2]*0.6,40); g.strokeWeight(Math.max(1,u*0.0011));
    for (let i=0;i<5;i++){ const t=i/4; g.line(cx-0.24*s+t*0.28*s, cy+0.02*s, cx-0.06*s+t*0.20*s, cy-0.16*s); } g.noStroke();
    // ---- keybed frame ----
    g.fill(C.sharp[0],C.sharp[1],C.sharp[2]*0.8,100);
    g.rect(kbL-kw*0.4, kbY-kbH*0.35, (kbR-kbL)+kw*0.8, kbH*1.5, s*0.004);
    // white keys
    for (let i=0;i<nWhite;i++){ const x=kbL+i*kw;
      g.fill(C.key[0],C.key[1],C.key[2],100); g.rect(x+kw*0.06, kbY, kw*0.88, kbH, kw*0.06);
      g.fill(C.key[0],C.key[1]*0.5,C.key[2]*0.85,60); g.rect(x+kw*0.06, kbY+kbH*0.8, kw*0.88, kbH*0.2); // key front shadow
    }
    // black keys (2-3 pattern)
    const patt=[1,1,0,1,1,1,0];
    for (let i=0;i<nWhite-1;i++){ if(patt[i%7]){ const x=kbL+(i+1)*kw;
      g.fill(C.sharp[0],C.sharp[1],C.sharp[2],100); g.rect(x-kw*0.28, kbY, kw*0.56, kbH*0.62, kw*0.05);
      g.fill(C.sharp[0],C.sharp[1],C.sharp[2]*2.2,80); g.rect(x-kw*0.28, kbY, kw*0.56, kbH*0.12); } }
    g.pop();
  }
  S.kbL=kbL; S.kw=kw; S.kbY=kbY; S.kbH=kbH;
}
image(S.bg, 0, 0);

// ---- warm spotlight glow over the instrument (real-time breathe) ----
push(); blendMode(ADD); noStroke();
const breathe = 0.7 + 0.3*Math.sin(K.t*0.6) + K.swell*0.15;
for (let r=5;r>0;r--){ const t=r/5; fill(C.spot[0],C.spot[1]*0.6,C.spot[2], 7*breathe*(1-t*0.3)); ellipse(cx, cy-0.02*s, s*1.1*t, s*0.7*t); }
pop();

// ---- act shaping ----
let waveAmp=1, waveSpd=1;
if (P.act==='crescendo'){ waveAmp = 0.4 + K.intensity*1.6; }
else if (P.act==='jazz'){ waveSpd = 1.6; waveAmp = 0.8+K.pulse*0.8; }
else { waveAmp = 0.85 + Math.sin(K.t*0.4)*0.15; } // recital

// ---- animated keys: traveling ripple + fft, always moving ----
push();
const kbL2=S.kbL, kw2=S.kw, kbY2=S.kbY, kbH2=S.kbH;
const drive = waveAmp*(0.6 + K.intensity*0.5 + P.energy*0.4);
for (let i=0;i<nWhite;i++){
  // baseline traveling wave (never re-phases: uses K.t continuously)
  let a = Math.max(0, Math.sin(i*0.55 - K.t*3.0*P.speed*waveSpd));
  a = a*a; // sharpen
  // beat accent
  a += K.pulse * (0.4+0.6*fr(i*3+Math.floor(K.beat))) * 0.7;
  // audio on top (mid-bins) — zero-safe
  const bin = Math.min(31, Math.floor(i/nWhite*32));
  a += (A.fft && A.fft[bin] ? A.fft[bin] : 0)*0.9 + S.mid*0.3;
  a = Math.min(1, a*drive);
  if (a<0.03) continue;
  const x = kbL2+i*kw2;
  // depressed key: lit warm overlay + drop
  push(); blendMode(C.wire?BLEND:ADD); noStroke();
  fill(C.spot[0], C.spot[1], Math.min(100,C.spot[2]+15), 55*a);
  rect(x+kw2*0.08, kbY2+kbH2*a*0.25, kw2*0.84, kbH2, kw2*0.06);
  // little sound bloom rising from struck key
  fill(C.gold[0],C.gold[1],C.gold[2], 40*a);
  ellipse(x+kw2*0.5, kbY2-kbH2*0.4*a, kw2*0.7*a, kbH2*0.9*a);
  pop();
}
pop();

// ---- lid specular shimmer (real-time sweep) ----
if (!C.wire && P.shimmer>0.02){
  push();
  drawingContext.save();
  // clip to the raised lid region
  const lox = -lidOpen*0.05*s, loy = -lidOpen*0.20*s;
  drawingContext.beginPath();
  const pts=WING; for (let i=0;i<pts.length;i++){ const p=pts[i]; const X=cx+lox+p[0]*s, Y=cy+loy+p[1]*s; if(i===0)drawingContext.moveTo(X,Y); else drawingContext.lineTo(X,Y);} drawingContext.closePath(); drawingContext.clip();
  blendMode(ADD); noStroke();
  const sweep = ((K.t*0.14)%1);
  const bx = cx-0.4*s + sweep*0.9*s;
  for (let b=0;b<3;b++){ const off=(b-1)*0.05*s;
    fill(C.sheen[0],C.sheen[1],C.sheen[2], 22*P.shimmer*(1-Math.abs(b-1)*0.4));
    quad(bx+off-0.03*s, cy-0.28*s+loy, bx+off+0.03*s, cy-0.28*s+loy, bx+off+0.09*s, cy+0.12*s+loy, bx+off+0.03*s, cy+0.12*s+loy);
  }
  drawingContext.restore();
  pop();
}

// ---- candelabra (optional) with real-time flame flicker ----
if (nCandle>0 && !C.wire){
  push();
  const bx = cx-0.16*s, by = cy-0.06*s;
  stroke(C.gold[0],C.gold[1],C.gold[2]*0.8,90); strokeWeight(s*0.006); noFill();
  line(bx, by, bx, by-0.10*s);
  for (let c=0;c<nCandle;c++){
    const cxp = bx + (c-(nCandle-1)/2)*0.05*s;
    const topY = by-0.10*s;
    stroke(C.gold[0],C.gold[1],C.gold[2]*0.8,90); line(bx, by-0.10*s, cxp, topY);
    noStroke(); fill(C.key[0],10,90,100); rect(cxp-s*0.004, topY-0.04*s, s*0.008, 0.04*s); // candle
    // flame
    const fl = 0.7+0.3*Math.sin(K.t*9+c*2.1)+0.2*fr(Math.floor(K.t*20)+c);
    push(); blendMode(ADD);
    fill(30,80,100, 70); ellipse(cxp+Math.sin(K.t*6+c)*s*0.003, topY-0.05*s, s*0.012*fl, s*0.03*fl);
    fill(50,60,100, 90); ellipse(cxp, topY-0.052*s, s*0.006*fl, s*0.018*fl);
    pop();
  }
  pop();
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;
